BEGIN; CREATE OR REPLACE FUNCTION public.get_own_profile() RETURNS SETOF public.profiles LANGUAGE plpgsql SECURITY DEFINER AS $$$ DECLARE v_row public.profiles; BEGIN FOR v_row IN SELECT * FROM public.profiles WHERE id = auth.uid() LOOP v_row.password_hash := NULL; v_row.password := NULL; RETURN NEXT v_row; END LOOP; END; $$$; CREATE OR REPLACE FUNCTION public.get_available_profiles() RETURNS SETOF public.profiles LANGUAGE plpgsql SECURITY DEFINER AS $$$ DECLARE v_row public.profiles; BEGIN FOR v_row IN SELECT * FROM public.profiles LOOP v_row.password_hash := NULL; v_row.password := NULL; RETURN NEXT v_row; END LOOP; END; $$$; COMMIT;
